import java.nio.file.*;

public class Main {
    public static void main(String[] args) {
        Path p = Path.of("/data/a/b/../c/./file.txt");
        System.out.println("original    : " + p);
        System.out.println("normalize() : " + p.normalize());
        System.out.println("(normalize is pure syntax, it does NOT touch the filesystem)");

        Path base = Path.of("/data");
        System.out.println("base.resolve(rel)      : " + base.resolve("x/y.txt"));
        System.out.println("base.resolve(absolute) : " + base.resolve("/etc/passwd")
                + "   <-- absolute replaces base");

        Path f = Path.of("/data/a/b/file.txt");
        System.out.println("relativize to /data/a  : " + Path.of("/data/a").relativize(f));

        // normalize() cannot stop path traversal: it just rewrites the string
        Path evil = Path.of("/data/uploads").resolve("../../etc/passwd").normalize();
        System.out.println("normalize(traversal)   : " + evil);
        System.out.println("still under /data/uploads ? " + evil.startsWith("/data/uploads"));

        // the real check needs a canonical (symlink-resolved) path
        Path safe = Path.of("/data/uploads/2026/ok.txt").normalize();
        System.out.println("normalize(safe path)   : " + safe);
        System.out.println("safe under /data/uploads ? " + safe.startsWith("/data/uploads"));
        System.out.println("parent / file name     : " + safe.getParent() + " | " + safe.getFileName());
        System.out.println("root / name count      : " + safe.getRoot() + " | " + safe.getNameCount());
    }
}
